import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('budget.xlsx') as z:
    print("Zip entries:", z.namelist())

    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    wbroot = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = wbroot.find('m:sheets', NS)
    for sh in sheets.findall('m:sheet', NS):
        name = sh.get('name')
        rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        print(f"Sheet: {name} rid={rid}")

    # resolve sheet -> file via workbook.xml.rels
    relroot = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {}
    for rel in relroot:
        relmap[rel.get('Id')] = rel.get('Target')

    for sh in sheets.findall('m:sheet', NS):
        name = sh.get('name')
        rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        target = relmap[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target
        print(f"\n--- Sheet: {name} ---")
        sroot = ET.fromstring(z.read(target))
        for row in sroot.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = v.text if v is not None else None
                if t == 's' and val is not None:
                    val = shared[int(val)]
                if val is not None:
                    print(f"{ref}: {val!r} (type={t})")

